/**
 * 世界书资源条目的约定名称与匹配规则
 *
 * 条目名允许自定义前缀/后缀（例如 `01.[res]资源库`、`03.[res]角色语音`），
 * 只要名称中连续包含下方约定字符串即可被识别。
 */

/** 资源库条目的约定名称 */
export const RESOURCE_ENTRY_NAME = '[res]资源库';

/** 语音配置条目的约定名称 */
export const VOICE_ENTRY_NAME = '[res]角色语音';

/** 输出守则条目的约定关键词 */
export const RULE_ENTRY_KEYWORD = '输出守则';

/**
 * 判断条目名是否为资源库条目
 * 严格匹配「包含 [res]资源库」的名称，允许在前后自定义前缀/后缀
 */
export function isResourceEntryName(name: string): boolean {
  return (name || '').includes(RESOURCE_ENTRY_NAME);
}

/**
 * 判断条目名是否为输出守则条目
 * 匹配「包含 输出守则」的名称，允许在前后自定义前缀/后缀
 */
export function isRuleEntryName(name: string): boolean {
  return (name || '').includes(RULE_ENTRY_KEYWORD);
}

/**
 * 判断条目名是否为语音配置条目
 * 严格匹配「包含 [res]角色语音」的名称，允许在前后自定义前缀/后缀
 */
export function isVoiceConfigEntryName(name: string): boolean {
  return (name || '').includes(VOICE_ENTRY_NAME);
}
