/**
 * 资源 key 注入脚本
 *
 * 读取世界书中的资源库条目，提取可用 key 列表并注入给 AI，
 * 让 AI 只能使用真实存在的资源 key，避免编造。
 *
 * 条目名允许自定义前缀/后缀，只要包含 `[res]资源库` 即可（匹配规则见 util/worldbookEntryNames.ts）。
 */

import { isResourceEntryName, isRuleEntryName } from '@util/worldbookEntryNames';

const INJECT_ID = 'wasteland-echoes-resource-keys';

/** 获取所有相关的世界书名称 */
function getAllWorldbookNames(): string[] {
  const charWorldbooks = getCharWorldbookNames('current');
  const worldbookNames: string[] = [];

  if (charWorldbooks.primary) worldbookNames.push(charWorldbooks.primary);
  worldbookNames.push(...charWorldbooks.additional);
  worldbookNames.push(...getGlobalWorldbookNames());

  return [...new Set(worldbookNames)];
}

/** 检查“输出守则”条目是否处于开启（enabled）状态 */
async function isRuleEntryEnabled(): Promise<boolean> {
  const wbNames = getAllWorldbookNames();

  for (const wbName of wbNames) {
    try {
      const entries = await getWorldbook(wbName);
      const ruleEntry = entries.find(e => isRuleEntryName(e.name));
      if (ruleEntry) {
        return ruleEntry.enabled === true;
      }
    } catch (err) {
      console.warn('[资源key注入] 检查世界书守则条目失败：' + wbName, err);
    }
  }

  // 也兜底检查角色卡内置世界书（若未走常规世界书命名）
  try {
    const rawChar = RawCharacter.find({ name: 'current' });
    if (rawChar) {
      const charObj = new RawCharacter(rawChar);
      const book = charObj.getCharacterBook();
      if (book?.entries) {
        const found = book.entries.find(e => isRuleEntryName(e.comment || ''));
        if (found) {
          return found.enabled === true;
        }
      }
    }
  } catch {
    // 忽略兜底检查的异常
  }

  return false;
}

/** 顶级分类标题 */
const SECTION_HEADERS = ['角色立绘', '背景图', 'CG', 'BGM'];

/** 将 YAML 内容按顶级分类拆分为 { 分类名: 内容 } */
function splitSections(yamlContent: string): Record<string, string> {
  const result: Record<string, string> = {};
  const headerPattern = new RegExp(`^(${SECTION_HEADERS.join('|')}):\\s*$`, 'm');
  let remaining = yamlContent;

  while (true) {
    const match = remaining.match(headerPattern);
    if (!match) break;

    const headerName = match[1];
    const startIdx = (match.index ?? 0) + match[0].length;
    remaining = remaining.substring(startIdx);

    // 找下一个顶级分类的起始位置
    const nextMatch = remaining.match(headerPattern);
    const sectionContent = nextMatch ? remaining.substring(0, nextMatch.index ?? 0) : remaining;
    result[headerName] = sectionContent;

    if (!nextMatch) break;
    remaining = remaining.substring(nextMatch.index ?? 0);
  }

  return result;
}

/** 从 YAML 内容提取 key 列表 */
function buildKeysSummary(yamlContent: unknown): string | null {
  try {
    if (!yamlContent || typeof yamlContent !== 'string') {
      console.warn('[资源key注入] YAML内容为空');
      return null;
    }

    const lines = [
      '<资源key>',
      '以下为唯一合法枚举，不得编造、不得自行补充；未列出时只能使用"暂无"',
      '[可用资源key]',
    ];
    const sections = splitSections(yamlContent);

    // 提取角色立绘 — 二级为角色名，三级为表情名
    if (sections['角色立绘']) {
      const charBlocks = sections['角色立绘'].split(/\n(?=[ \t]{2}\S)/);
      const chars: string[] = [];
      for (const block of charBlocks) {
        const nameMatch = block.match(/^\s{2}(\S[^:]*?):\s*$/m);
        if (nameMatch) {
          const faces = [...block.matchAll(/\n\s{4}(\S[^:]*?):\s/g)].map(m => m[1].trim());
          if (faces.length) {
            chars.push(nameMatch[1].trim() + '(' + faces.join(',') + ')');
          }
        }
      }
      if (chars.length) lines.push('角色立绘: ' + chars.join(', '));
    }

    // 提取背景图 / BGM / CG — 二级为 key 名
    for (const section of ['背景图', 'BGM', 'CG']) {
      if (sections[section]) {
        const keys = [...sections[section].matchAll(/\n\s{2}(\S[^:]*?):\s/g)].map(m => m[1].trim());
        if (keys.length) lines.push(section + ': ' + keys.join(', '));
      }
    }

    // 仅剩顶部3行说明、没有任何分类内容时视为解析失败
    if (lines.length <= 3) {
      return null;
    }
    lines.push('</资源key>');

    console.info('[资源key注入] 解析完成，共' + lines.length + '行');
    return lines.join('\n');
  } catch (e) {
    console.error('[资源key注入] 解析失败:', e);
    return null;
  }
}

/** 查找资源条目内容 */
async function findResourceContent(): Promise<string | null> {
  const uniqueNames = getAllWorldbookNames();

  for (const wbName of uniqueNames) {
    try {
      const entries = await getWorldbook(wbName);
      const entry = entries.find(e => isResourceEntryName(e.name));
      if (entry && entry.content) {
        console.info('[资源key注入] 找到资源条目：' + entry.name + ' in ' + wbName);
        return entry.content;
      }
    } catch (err) {
      console.warn('[资源key注入] 读取世界书失败：' + wbName, err);
    }
  }
  return null;
}

async function init() {
  console.info('[资源key注入] 脚本开始执行...');

  let currentResult: { uninject: () => void } | null = null;

  async function refreshInjection() {
    // 1. 检查包含“输出守则”的条目是否处于开启状态
    const ruleEnabled = await isRuleEntryEnabled();
    if (!ruleEnabled) {
      console.info('[资源key注入] 「输出守则」条目未处于打开状态，清除注入并跳过');
      if (currentResult && currentResult.uninject) {
        currentResult.uninject();
        currentResult = null;
      }
      return;
    }

    // 2. 只有开启状态下才读取资源库内容并注入
    const content = await findResourceContent();
    if (!content) {
      console.warn('[资源key注入] 未找到资源条目');
      if (currentResult && currentResult.uninject) {
        currentResult.uninject();
        currentResult = null;
      }
      return;
    }

    const summary = buildKeysSummary(content);
    if (!summary) {
      console.warn('[资源key注入] 解析失败');
      if (currentResult && currentResult.uninject) {
        currentResult.uninject();
        currentResult = null;
      }
      return;
    }

    // 先清理旧的注入
    if (currentResult && currentResult.uninject) {
      currentResult.uninject();
    }

    currentResult = injectPrompts([
      {
        id: INJECT_ID,
        position: 'in_chat',
        depth: 0,
        role: 'system',
        should_scan: true,
        content: summary,
      },
    ]);

    console.info('[资源key注入] ✅ 输出守则已打开，系统资源库注入成功，长度：' + summary.length);
  }

  // 初始注入判断
  await refreshInjection();

  // 每次生成前夕重新检测守则条目状态并刷新注入配置
  const unsubscribeGen = eventOn(tavern_events.GENERATION_STARTED, async () => {
    console.info('[资源key注入] 新一轮生成，检测输出守则状态并刷新资源注入');
    await refreshInjection();
  });

  // 监听世界书变动事件（若酒馆在运行时修改了世界书开关）
  const unsubscribeWb = eventOn(tavern_events.WORLDINFO_UPDATED, async () => {
    console.info('[资源key注入] 世界书内容/状态更新，重新检测输出守则');
    await refreshInjection();
  });

  // 页面卸载，销毁注入与监听
  $(window).on('pagehide', () => {
    if (currentResult && currentResult.uninject) currentResult.uninject();
    unsubscribeGen.stop();
    unsubscribeWb.stop();
  });
}

$(() => {
  errorCatched(init)();
});
